      assert.equal(result.operation_result_status, "failed_safely");
      assert.equal(result.operation_kind, "persist_approved_memory");
      assert.equal(result.error_kind, "postgres_unique_conflict");
      assert.equal(status.failed_operation_count, 1);
      assert.equal(status.failure_count_by_kind.postgres_unique_conflict, 1);
      assert.equal(serialized.includes("secret-user"), false);
      assert.equal(serialized.includes("secret-pass"), false);
      assert.equal(serialized.includes("postgres://"), false);
      assert.equal(serialized.includes("private text"), false);
      assert.equal(serialized.includes("Failure private summary"), false);
      assert.equal(serialized.includes("insert into"), false);
      assertPostgresPersistenceFailureResultSafe(result);
      assertPostgresPersistenceAdapterStatusSafe(status);
