      assert.deepEqual(plan.missing_required_env, ["IRIS_POSTGRES_CONNECTION_STRING"]);
      assert.equal(plan.ssl_mode_policy, "prefer");
      assert.equal(plan.max_pool_size, 100);
      assert.equal(plan.idle_timeout_ms, 30000);
      assert.equal(plan.statement_timeout_ms, 1000);
      assert.equal(serialized.includes("unsafe-postgres"), false);
      assert.equal(serialized.includes("postgres://"), false);
      assertPostgresPoolFactoryPlanSafe(plan);
