      assert.equal(status.bridge_endpoint_scope, "external");
      assert.equal(status.bridge_endpoint_locality_ok, false);
      assert.equal(status.last_error, "local_endpoint_policy_blocked");
      assert.equal(serialized.includes("https://example.com"), false);
