      assert.equal(cliReport.ok, true);
      assert.equal(cliReport.schema, "iris_admin_operations_summary_cli_v1");
      assert.equal(
        cliReport.admin_operations_summary.schema,
        "iris_admin_operations_summary_v1"
      );
