      assert.equal(result.adapter_response_summary.request_id, "control-invalid-timeout");
      assert.equal(adapter.status().game_control_readiness_status, "active");
      assert.equal(adapter.status().accepted_count, 1);
      assertHttpGameControlAdapterStatusSafe(adapter.status());
      assertGameControlResultSafe(result);
