      assert.equal(result.phase03.context_tags.includes("game"), true);
      assert.equal(result.phase04.action_type, "SPEAK");
      assert.equal(result.phase07.task_type, "CREATE_CONTENT");
      assert.match(result.phase15.final_text, /watching the game/);
      assert.equal(Object.hasOwn(result.phase15, "world_command"), false);

