      assert.equal(observedBatchLimit, 10);
      assert.equal(tick.ok, true);
      assert.equal(tick.processed_count, 1);
      assert.equal(status.interval_ms, 3000);
      assert.equal(status.batch_limit, 10);
      assert.equal(status.processed_count, 1);
      assert.equal(serialized.includes("invalid numeric ingest fixture"), false);
      assert.equal(serialized.includes("input_action_candidate"), false);
